// Deriva a lista de obras DIRETO dos dados recebidos (cada OC já vem com
// obra_id + obra_nome) -- NÃO mantém mais uma lista própria de obras aqui.
// Motivo: a 1ª carga real trouxe a obra id 103 "CNPEM - AUDITÓRIO", que
// não existe no array OBRAS do painel-mse (só tem 106/110/94/107/108/91).
// Uma lista fixa teria descartado essa obra em silêncio -- contra a regra
// do projeto de nunca sumir com dado sem avisar (ADR-005). Gravar TODAS as
// obras que aparecerem aqui, mesmo que o painel ainda não tenha aba pra
// mostrar; decidir o que exibir é problema do front-end, não da ingestão.
const resposta = $input.first().json;
const todasOcs = Array.isArray(resposta.data) ? resposta.data : [];

const porObra = new Map();
for (const oc of todasOcs) {
  const idObra = Number(oc.obra_id);
  if (!Number.isFinite(idObra)) continue; // OC sem obra_id numérico válido -- não deveria acontecer; não trava o resto da carga
  if (!porObra.has(idObra)) {
    porObra.set(idObra, { id_obra: idObra, nome_obra: oc.obra_nome || null, ocs: [] });
  }
  porObra.get(idObra).ocs.push(oc);
}

return Array.from(porObra.values()).map(obra => ({
  json: { ...obra, total: obra.ocs.length },
}));

// Reconstrói o registro completo da obra: os dados vindos de "Agrupar OCs
// por obra" (ocs, total, nome) + o resumo financeiro que acabou de chegar
// desta chamada (1 por obra, pareado pelo item de origem via pairedItem
// automático do n8n). IMPORTANTE: este node precisa estar em modo "Run
// Once for Each Item" (parameters.mode acima) -- no modo padrão ("Run
// Once for All Items") o código roda 1 VEZ SÓ pro workflow inteiro e
// devolve 1 item só, mesmo com várias obras chegando aqui (foi assim que
// a 1ª rodada completa só gravou 1-2 obras em vez de todas, sem erro
// nenhum reportado -- o node "funcionou", só que processou tudo como se
// fosse 1 item).
const original = $('Agrupar OCs por obra').item.json;
const resumo = $input.item.json;

return {
  json: {
    id_obra: original.id_obra,
    nome_obra: original.nome_obra,
    total: original.total,
    ocs: original.ocs,
    resumo: resumo,
    atualizado_em: new Date().toISOString(),
  },
};
